// The Dart labelling rule must give exactly the levels of the Python
// reference (telemonitor-research/src/telemonitor/labels.py). The fixture is
// generated by the reference on every boundary of every channel.
import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:telemonitor/services/clinical_levels.dart';

void main() {
  final fx = jsonDecode(File('test/fixtures/levels_parity.json').readAsStringSync())
      as Map<String, dynamic>;

  test('same threshold-table version as the research code', () {
    expect(ClinicalLevels.version, fx['version']);
  });

  void channel(String name, int? Function(num?) f) {
    test('$name levels match the reference on every value', () {
      final values = (fx[name]['values'] as List).cast<num>();
      final levels = fx[name]['levels'] as List;
      for (var i = 0; i < values.length; i++) {
        expect(f(values[i]), levels[i], reason: '$name = ${values[i]}');
      }
    });
  }

  channel('sbp', ClinicalLevels.sbp);
  channel('dbp', ClinicalLevels.dbp);
  channel('pulse', ClinicalLevels.pulse);
  channel('glucose', ClinicalLevels.glucose);

  test('condition and overall levels match, with missing channels', () {
    for (final c in (fx['combined'] as List).cast<Map<String, dynamic>>()) {
      final h = ClinicalLevels.haemodynamic(sbp: c['sbp'], dbp: c['dbp'], hr: c['hr']);
      final g = ClinicalLevels.glycaemic(c['glucose']);
      final y = ClinicalLevels.overall(
          sbp: c['sbp'], dbp: c['dbp'], hr: c['hr'], glucoseMmol: c['glucose']);
      expect(h, c['haemodynamic'], reason: '$c');
      expect(g, c['glycaemic'], reason: '$c');
      expect(y, c['overall'], reason: '$c');
    }
  });

  test('1.80 g/L is exactly the 180 mg/dL treatment threshold', () {
    expect(ClinicalLevels.glucose(1.80 * 1000 / (10 * ClinicalLevels.mgdlPerMmol)), 2);
  });
}
